#include <bits/stdc++.h>
using namespace std;const int N=256,P=998244353,G=3;int a[N],b[N],c[N],d[N],x[N],y[N],r[N],o[N];int q(int a,int b=P-2){int s=1;for(;b;b>>=1,a=1LL*a*a%P)if(b&1)s=1LL*s*a%P;return s;}void f(int*a,int n,int z){for(int i=0;i<n;i++)if(i<r[i])swap(a[i],a[r[i]]);for(int l=2;l<=n;l<<=1){int w=q(G,(P-1)/l);if(z<0)w=q(w);for(int i=0;i<n;i+=l)for(int j=0,t=1;j<l/2;j++,t=1LL*t*w%P){int u=a[i+j],v=1LL*t*a[i+j+l/2]%P;a[i+j]=(u+v)%P;a[i+j+l/2]=(u-v+P)%P;}}if(z<0){int w=q(n);for(int i=0;i<n;i++)a[i]=1LL*a[i]*w%P;}}void m(int*a,int n,int*b,int k,int*c,int z){int l=1,h=0;while(l<n+k-1)l<<=1;while((1<<h)<l)h++;for(int i=0;i<l;i++)x[i]=i<n?a[i]:0,y[i]=i<k?b[i]:0,r[i]=(r[i>>1]>>1)|((i&1)<<(h-1));f(x,l,1);f(y,l,1);for(int i=0;i<l;i++)x[i]=1LL*x[i]*y[i]%P;f(x,l,-1);for(int i=0;i<z;i++)c[i]=x[i];}void h(int*a,int*b,int n){memset(b,0,n*sizeof(int));b[0]=q(a[0]);for(int k=1;k<n;k<<=1){int z=min(k<<1,n),l=1,t=0;while(l<z+k)l<<=1;while((1<<t)<l)t++;for(int i=0;i<l;i++)x[i]=i<z?a[i]:0,y[i]=i<k?b[i]:0,r[i]=(r[i>>1]>>1)|((i&1)<<(t-1));f(x,l,1);f(y,l,1);for(int i=0;i<l;i++)y[i]=1LL*y[i]*(2-1LL*x[i]*y[i]%P+P)%P;f(y,l,-1);for(int i=0;i<z;i++)b[i]=y[i];}}int main(int C,char**v){ios::sync_with_stdio(0);cin.tie(0);int R=C>1?stoi(v[1]):1000;unsigned long long z=C>2?stoull(v[2]):1;mt19937_64 g(z);while(R--){int n=g()%60+1;memset(a,0,sizeof a);memset(o,0,sizeof o);a[0]=1;for(int i=1;i<n;i++)a[i]=g()%P;for(int k=1;k<n;k++){long long s=1LL*k*a[k]%P;for(int i=1;i<k;i++)s-=1LL*i*o[i]%P*a[k-i]%P;o[k]=(s%P+P)%P*q(k)%P;}h(a,b,n);for(int i=1;i<n;i++)d[i-1]=1LL*i*a[i]%P;c[0]=0;if(n>1)m(d,n-1,b,n,c+1,n-1);for(int i=1;i<n;i++)c[i]=1LL*c[i]*q(i)%P;for(int i=0;i<n;i++)if(c[i]!=o[i])return cout<<"WA\n",1;}cout<<"OK\n";}
